		global.Protocol.AllowByName = map[string]string{"file": config.ProtocolAlways}
		testconfig.Register(*global, *config.NewConfig())

		require.NoError(t, sm.UpdateContext(context.Background(), &SubmoduleUpdateOptions{}))
	})
}

